// Creates .env.local with a fresh APP_SECRET. Safe to re-run: it never
// overwrites an existing file.
import { existsSync, writeFileSync } from "node:fs";
import { randomBytes } from "node:crypto";

const file = new URL("../.env.local", import.meta.url);
if (existsSync(file)) {
  console.log(".env.local already exists, leaving it alone.");
  process.exit(0);
}

const secret = randomBytes(32).toString("base64url");
writeFileSync(
  file,
  [
    "# Generated by `pnpm setup`. Never commit this file.",
    `APP_SECRET=${secret}`,
    "APP_URL=http://localhost:3000",
    "DATABASE_URL=file:./data/nest-deploy.db",
    "",
    "# Local development only: sign in without Hack Club Auth.",
    "DEV_LOGIN=1",
    "",
    "# Hack Club Auth (https://auth.hackclub.com/developer/apps)",
    "HACKCLUB_CLIENT_ID=",
    "HACKCLUB_CLIENT_SECRET=",
    "",
    "# GitHub App (see docs/backend-setup.md)",
    "GITHUB_APP_ID=",
    "GITHUB_APP_SLUG=",
    "GITHUB_APP_CLIENT_ID=",
    "GITHUB_APP_CLIENT_SECRET=",
    "GITHUB_APP_PRIVATE_KEY=",
    "GITHUB_WEBHOOK_SECRET=",
    "",
    "# 1 = the website also runs the deployment queue (one process is enough).",
    "RUN_WORKER=1",
    "",
    "# docker isolates builds. local runs them on this machine: dev only.",
    "BUILD_RUNNER=docker",
    "",
  ].join("\n"),
  { mode: 0o600 }
);
console.log("Created .env.local with a new APP_SECRET.");
